  _build(node, left, right, values) {
    if (right - left === 1) {
      this._sums[node] = values[left];
      this._maxima[node] = values[left];
      return;
    }
    const middle = Math.floor((left + right) / 2);
    this._build(node * 2, left, middle, values);
    this._build(node * 2 + 1, middle, right, values);
