'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');

test('assignment supersedes pending additions at parent and child nodes', () => {
  const tree = new RangeTree([1, 2, 3, 4, 5, 6, 7, 8]);
  tree.add(0, 4, 7);
  tree.add(4, 8, -3);
  tree.assign(0, 8, 0);
  tree.add(0, 8, -2);
  tree.assign(2, 6, -9);
  tree.add(3, 7, 4);
  assert.equal(tree.sum(1, 7), -24);
  assert.equal(tree.max(0, 3), -2);
  assert.deepEqual(tree.toArray(), [-2, -2, -9, -5, -5, -5, 2, -2]);
});

test('threshold searches see unpropagated assignments and additions', () => {
  const tree = new RangeTree([1, 2, 3, 4, 5]);
  tree.assign(0, 5, -10);
  tree.add(0, 5, 12);
  assert.equal(tree.firstAtLeast(1, 2), 1);
  tree.assign(0, 5, -20);
  assert.equal(tree.firstAtLeast(0, 0), -1);
  tree.add(2, 5, 30);
  assert.equal(tree.firstAtLeast(1, 10), 2);
  assert.equal(tree.firstAtLeast(3, 10), 3);
  assert.equal(tree.firstAtLeast(5, -Infinity), -1);
  assert.equal(tree.firstAtLeast(0, Infinity), -1);
  assert.equal(tree.firstAtLeast(0, -Infinity), 0);
});

test('negative partial maxima and empty ranges retain their identities', () => {
  const tree = new RangeTree([-5, -2, -7, -3, -1]);
  assert.equal(tree.max(0, 2), -2);
  assert.equal(tree.max(2, 4), -3);
  for (let i = 0; i <= tree.length; i++) {
    assert.equal(tree.sum(i, i), 0);
    assert.equal(tree.max(i, i), -Infinity);
    assert.equal(tree.assign(i, i, 99), undefined);
    assert.equal(tree.add(i, i, 99), undefined);
  }
  assert.deepEqual(tree.toArray(), [-5, -2, -7, -3, -1]);
});

test('validation is atomic, length is read-only, and arrays do not alias', () => {
  for (const input of [null, {}, [], [NaN], [Infinity], [-Infinity], ['1'], new Array(2)]) {
    assert.throws(() => new RangeTree(input), RangeError);
  }
  const input = [1, 2, 3];
  const tree = new RangeTree(input);
  input[0] = 500;
  assert.equal(tree.get(0), 1);
  assert.throws(() => { tree.length = 99; }, TypeError);
  assert.equal(tree.length, 3);
  tree.add(0, 3, 5);
  tree.assign(0, 3, -4);
  for (const [l, r] of [[-1, 2], [0, 4], [2, 1], [0.5, 2], [0, NaN], ['0', 2], [0, Infinity]]) {
    for (const method of ['sum', 'max', 'assign', 'add']) {
      assert.throws(() => tree[method](l, r, 10), RangeError);
    }
  }
  for (const value of [NaN, Infinity, -Infinity, '2', null, undefined]) {
    for (const method of ['assign', 'add']) {
      assert.throws(() => tree[method](0, 3, value), RangeError);
      assert.throws(() => tree[method](1, 1, value), RangeError);
    }
  }
  for (const index of [-1, 3, 0.5, NaN, Infinity, '1']) {
    assert.throws(() => tree.get(index), RangeError);
  }
  for (const [lo, x] of [[-1, 0], [4, 0], [0.5, 0], ['0', 0], [0, NaN], [0, '1'], [0, null]]) {
    assert.throws(() => tree.firstAtLeast(lo, x), RangeError);
  }
  assert.deepEqual(tree.toArray(), [-4, -4, -4]);
  const result = tree.toArray();
  result[1] = 500;
  assert.equal(tree.get(1), -4);
});

test('deterministic mixed workloads agree with an array model', () => {
  let state = 0x12345678;
  function random(n) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % n;
  }
  for (const n of [1, 2, 3, 5, 8, 13, 33]) {
    const values = Array.from({ length: n }, () => random(41) - 20);
    const tree = new RangeTree(values);
    for (let step = 0; step < 2000; step++) {
      for (let batch = 0, count = 1 + random(4); batch < count; batch++) {
        let l = random(n + 1), r = random(n + 1);
        if (l > r) [l, r] = [r, l];
        if (step % 11 === 0) { l = 0; r = n; }
        const value = random(41) - 20;
        if (random(2)) {
          assert.equal(tree.assign(l, r, value), undefined);
          for (let i = l; i < r; i++) values[i] = value;
        } else {
          assert.equal(tree.add(l, r, value), undefined);
          for (let i = l; i < r; i++) values[i] += value;
        }
      }
      const lo = random(n + 1);
      const x = step % 17 === 0 ? Infinity : step % 19 === 0 ? -Infinity : random(101) - 50;
      assert.equal(tree.firstAtLeast(lo, x), values.findIndex((v, i) => i >= lo && v >= x));
      let l = random(n + 1), r = random(n + 1);
      if (l > r) [l, r] = [r, l];
      const slice = values.slice(l, r);
      assert.equal(tree.sum(l, r), slice.reduce((a, b) => a + b, 0));
      assert.equal(tree.max(l, r), Math.max(...slice));
      const index = random(n);
      assert.equal(tree.get(index), values[index]);
      if (step % 101 === 0) assert.deepEqual(tree.toArray(), values);
    }
    for (let l = 0; l <= n; l++) {
      for (let r = l; r <= n; r++) {
        const slice = values.slice(l, r);
        assert.equal(tree.sum(l, r), slice.reduce((a, b) => a + b, 0));
        assert.equal(tree.max(l, r), Math.max(...slice));
      }
      for (const x of [-Infinity, -50, 0, 50, Infinity]) {
        assert.equal(tree.firstAtLeast(l, x), values.findIndex((v, i) => i >= l && v >= x));
      }
    }
    assert.deepEqual(tree.toArray(), values);
  }
});

